shaderSource:
uniform float2 resolution;
uniform float tiltX;
uniform float tiltY;

half4 main(float2 xy) {
  float2 uv = xy / max(resolution, float2(1.0, 1.0));
  float aspect = resolution.x / max(resolution.y, 1.0);
  float2 light = float2(0.30, 0.20) + float2(tiltX, tiltY) * 0.28;

  half3 deep = half3(0.04, 0.06, 0.10);
  half3 mid = half3(0.14, 0.20, 0.28);
  half3 lift = half3(0.32, 0.42, 0.55);
  half3 col = mix(deep, mid, 1.0 - uv.y);
  col = mix(col, lift, pow(1.0 - uv.y, 2.2) * 0.55);

  float2 e = min(uv, 1.0 - uv);
  float rim = 1.0 - smoothstep(0.0, 0.11, min(e.x * aspect, e.y));
  col += half3(0.70, 0.82, 1.0) * rim * 0.62;

  float top = smoothstep(0.0, 0.06, uv.y) * (1.0 - smoothstep(0.06, 0.32, uv.y));
  col += half3(0.92, 0.96, 1.0) * top * 0.28;

  float2 d = uv - light;
  d.x *= aspect;
  float spec = exp(-dot(d, d) * 22.0);
  float bloom = exp(-dot(d, d) * 6.0);
  col += half3(1.0, 1.0, 1.0) * spec * 0.95;
  col += half3(0.55, 0.72, 1.0) * bloom * 0.22;

  float2 fd = uv - float2(0.78 + tiltX * 0.08, 0.82 - tiltY * 0.06);
  fd.x *= aspect;
  col += half3(0.20, 0.35, 0.55) * exp(-dot(fd, fd) * 3.5) * 0.25;

  float occl = smoothstep(0.55, 1.0, uv.y);
  col *= mix(half3(1.0, 1.0, 1.0), half3(0.55, 0.58, 0.65), occl * 0.55);

  float alpha = 0.94;
  return half4(col, alpha);
}
